-- ---------------------------------------------------------------------------
-- Staff notification feed (NEW_ORDER, LOW_STOCK, …). Read by ADMIN and STORE_MANAGER;
-- also pushed live over STOMP to /topic/admin/notifications.
-- ---------------------------------------------------------------------------
CREATE TABLE notifications
(
    id           UUID PRIMARY KEY,
    type         VARCHAR(20)  NOT NULL,                    -- NEW_ORDER | LOW_STOCK | SYSTEM
    title        VARCHAR(150) NOT NULL,
    message      VARCHAR(500),
    reference_id UUID,                                     -- e.g. order id / product id
    is_read      BOOLEAN      NOT NULL DEFAULT FALSE,
    created_at   TIMESTAMPTZ  NOT NULL DEFAULT now(),
    CONSTRAINT ck_notification_type CHECK (type IN ('NEW_ORDER', 'LOW_STOCK', 'SYSTEM'))
);
CREATE INDEX ix_notifications_created ON notifications (created_at DESC);
CREATE INDEX ix_notifications_unread ON notifications (is_read) WHERE is_read = FALSE;
